from lxml import etree
z=zipfile.ZipFile('new.docx')
W='{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'
for n in z.namelist():
    if n.endswith('.xml') or n.endswith('.rels'):
        etree.fromstring(z.read(n))
print("all parts well-formed:", len(z.namelist()), "parts")
doc=etree.fromstring(z.read('word/document.xml'))
# check balance/nesting of comment markers
stack=[]
ok=True
for el in doc.iter():
    tag=el.tag.replace(W,'w:')
    if tag=='w:commentRangeStart': stack.append(el.get(W+'id'))
    elif tag=='w:commentRangeEnd':
        top=stack.pop() if stack else None
        if top!=el.get(W+'id'): ok=False; print("MISMATCH", top, el.get(W+'id'))
print("markers balanced:", ok and not stack)
# print the annotated paragraph text
for p in doc.iter(W+'p'):
    if p.find('.//'+W+'commentRangeStart') is not None and p.find('.//'+W+'commentReference') is not None:
        print("\nPARAGRAPH:\n", ''.join(t.text or '' for t in p.iter(W+'t')))
        print("refs:", [r.get(W+'id') for r in p.iter(W+'commentReference')])
